// Command protoc-gen-testplugin is a minimal protoc plugin used by the goprotoc
// tests to verify that plugins declared as tools in a module's go.mod are found
// and executed via "go tool".
//
// It deliberately depends on nothing outside the standard library, so that the
// module that declares it needs no go.sum and no network access. That means it
// encodes its CodeGeneratorResponse by hand instead of using protobuf runtime.
package main

import (
	"fmt"
	"io"
	"os"
)

const (
	// Field numbers within CodeGeneratorResponse.
	fieldResponseFile = 15
	// Field numbers within CodeGeneratorResponse.File.
	fieldFileName    = 1
	fieldFileContent = 15
)

func main() {
	// The request is not inspected; it is drained so the caller does not see a
	// broken pipe.
	if _, err := io.ReadAll(os.Stdin); err != nil {
		fmt.Fprintf(os.Stderr, "failed to read code gen request: %v\n", err)
		os.Exit(1)
	}

	var file []byte
	file = appendField(file, fieldFileName, []byte("testplugin-output.txt"))
	file = appendField(file, fieldFileContent, []byte("generated by protoc-gen-testplugin"))

	var resp []byte
	resp = appendField(resp, fieldResponseFile, file)

	if _, err := os.Stdout.Write(resp); err != nil {
		fmt.Fprintf(os.Stderr, "failed to write code gen response: %v\n", err)
		os.Exit(1)
	}
}

// appendField appends a length-delimited protobuf field to b.
func appendField(b []byte, fieldNum int, payload []byte) []byte {
	const wireTypeLengthDelimited = 2
	b = appendVarint(b, uint64(fieldNum)<<3|wireTypeLengthDelimited)
	b = appendVarint(b, uint64(len(payload)))
	return append(b, payload...)
}

func appendVarint(b []byte, v uint64) []byte {
	for v >= 0x80 {
		b = append(b, byte(v)|0x80)
		v >>= 7
	}
	return append(b, byte(v))
}
